(function(){'use strict';const en=document.documentElement.lang==='en',L=(a,b)=>en?b:a,workspace=document.querySelector('.heat-workspace'),panel=workspace?.querySelector('.inputs');if(!panel)return;const groups=[...panel.querySelectorAll('.heat-input-group')],originalOpen=groups.map(g=>g.open),definitions=[['room',L('Căn phòng','Room'),0,['area','height','tin','rhin']],['outside',L('Ngoài trời','Outdoors'),0,['tout','rhout','pressure']],['wall',L('Tường','Walls'),1,['wall','uwall','wallsolar']],['roof',L('Mái','Roof'),1,['roof','uroof','roofsolar']],['glass',L('Kính & nắng','Glass & sun'),1,['glass','uglass','irradiance','shgc','shade']],['people',L('Người & thiết bị','People & gains'),2,null],['air',L('Gió tươi & lọt khí','Outdoor air'),3,null],['ac',L('Chọn AC','AC selection'),4,null]];let mode='visual',active='room';const ui=document.createElement('section');ui.className='heat-visual';ui.innerHTML='<div class="heat-view-switch" role="group" aria-label="'+L('Cách nhập thông số','Input view')+'"><button type="button" data-view="visual">'+L('⌂ Trực quan','⌂ Visual')+'</button><button type="button" data-view="detail">'+L('☷ Toàn bộ thông số','☷ All inputs')+'</button></div><div class="heat-scene"><div class="scene-caption">'+L('Chọn một vị trí để nhập thông số','Select a location to enter its inputs')+'</div><svg viewBox="0 0 620 380" aria-hidden="true"><defs><linearGradient id="room-floor" x2="1" y2="1"><stop stop-color="#b5ded0"/><stop offset="1" stop-color="#e0efde"/></linearGradient><linearGradient id="room-wall"><stop stop-color="#f1f8f4"/><stop offset="1" stop-color="#c5e0da"/></linearGradient></defs><circle cx="535" cy="66" r="28" fill="#f7d683"/><path d="M535 25v-9M535 107v9M494 66h-9M576 66h9M506 37l-7-7M564 95l7 7" stroke="#edc76b" stroke-width="4"/><ellipse cx="315" cy="322" rx="220" ry="29" fill="#153e3610"/><path d="M96 173l213-93 222 98-218 119z" fill="#6c9c93"/><path d="M96 173v120l217 70V263z" fill="url(#room-wall)"/><path d="M313 263v100l218-103v-82z" fill="#dcefe8"/><path d="M96 293l217-101 218 68-218 103z" fill="url(#room-floor)"/><path d="M96 173l217 90 218-85" fill="none" stroke="#527b72" stroke-width="3"/><path d="M96 173v120l217 70 218-103v-82" fill="none" stroke="#729b90" stroke-width="3"/><path d="M96 173l213-125 222 130-222-98z" fill="#3e736c"/><path d="M125 145l184-110 189 109" fill="none" stroke="#7db8a8" stroke-width="5"/><path d="M374 226l84-35v65l-84 38z" fill="#92d2df" stroke="#4e9398" stroke-width="5"/><path d="M416 209v63M375 257l82-36" stroke="#e2f8f7" stroke-width="4"/><path d="M154 196l87 33v24l-87-31z" fill="#fff" stroke="#83aea5" stroke-width="2"/><path d="M164 217l68 26" stroke="#44887c" stroke-width="3"/><path class="scene-air" d="M187 241q25 50 87 59M198 243q33 33 82 35M467 230q-36 9-63 46" fill="none" stroke="#56b8bc" stroke-width="3" stroke-dasharray="7 6"/><path d="M247 277l50-22 42 15-50 24z" fill="#d6b68b"/><path d="M253 277v22M328 273v22" stroke="#977852" stroke-width="5"/><circle cx="354" cy="297" r="10" fill="#e6b38e"/><path d="M354 311v22M344 319h20" stroke="#4a7e8c" stroke-width="10" stroke-linecap="round"/></svg>'+definitions.map(([id,label])=>'<button type="button" class="scene-hotspot scene-'+id+'" data-target="'+id+'" aria-pressed="false">'+label+'</button>').join('')+'<div class="scene-live"><span id="scene-room-data"></span><span id="scene-air-data"></span></div></div><div class="scene-section-heading"><span>'+L('Thông số đang chỉnh','Editing inputs')+'</span><h3 id="scene-active-heading"></h3></div>';panel.insertBefore(ui,panel.querySelector('.heat-input-group'));const hint=document.createElement('p');hint.className='field-help scene-scope';hint.textContent=L('Hình minh họa giúp nhập liệu, không theo tỷ lệ và không mô phỏng tải theo giờ.','The illustration guides input; it is not to scale or an hourly thermal simulation.');ui.append(hint);function apply(){const visual=mode==='visual',def=definitions.find(d=>d[0]===active);workspace.classList.toggle('heat-visual-mode',visual);ui.classList.toggle('detail-mode',!visual);ui.querySelectorAll('[data-view]').forEach(b=>{const selected=b.dataset.view===mode;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});ui.querySelectorAll('[data-target]').forEach(b=>{b.classList.toggle('selected',b.dataset.target===active);b.setAttribute('aria-pressed',String(b.dataset.target===active));});groups.forEach((g,i)=>{g.hidden=visual&&i!==def[2];g.open=visual?true:originalOpen[i];for(const input of g.querySelectorAll('input')){const field=input.closest('.two-fields>div');if(field)field.hidden=visual&&i===def[2]&&def[3]&&!def[3].includes(input.id.slice(2));}});document.getElementById('scene-active-heading').textContent=def[1];}function values(){const v=id=>document.getElementById('c-'+id).value;document.getElementById('scene-room-data').textContent=v('area')+' m² · '+v('height')+' m · '+v('tin')+' °C';document.getElementById('scene-air-data').textContent=L('Gió tươi: ','Outdoor air: ')+v('fresh')+' m³/h';}ui.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.view)mode=button.dataset.view;if(button.dataset.target)active=button.dataset.target;apply();});panel.addEventListener('input',values);document.getElementById('c-reset').addEventListener('click',values);apply();values();})();
